#!/usr/bin/env node
// Builds database/00-ALL-IN-ONE.sql by concatenating the numbered migration
// files in order. Paste that single file into the Supabase SQL editor to set
// up a fresh project in one shot. Re-run after you add a new numbered file.

const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, '..', 'database');
const files = fs.readdirSync(dir)
  .filter((f) => /^\d\d-.*\.sql$/.test(f) && !f.startsWith('00-'))
  .sort();

const parts = [
  '-- =============================================',
  '-- ALL-IN-ONE SETUP — generated by scripts/bundle-sql.js',
  `-- Contains, in order: ${files.join(', ')}`,
  '-- Paste the whole file into Supabase → SQL Editor → Run.',
  '-- =============================================',
  ''
];
for (const f of files) {
  parts.push(`\n-- ######## ${f} ########\n`);
  parts.push(fs.readFileSync(path.join(dir, f), 'utf8'));
}
const out = path.join(dir, '00-ALL-IN-ONE.sql');
fs.writeFileSync(out, parts.join('\n'));
console.log(`Wrote ${out} (${files.length} files)`);
